//! ONNX post-processing regression tests using tiny handcrafted models.
//!
//! The ONNX fixtures under `tests/bughunt7_data/` are generated by the Python
//! scripts in that directory (constant-logit graphs built with `onnx.helper`,
//! tiny `tokenizers` vocabularies; no model downloads).
//!
//! Tests that need ONNX Runtime are opt-in: set `ANNO_BH7_ORT_LIB` to the
//! directory holding `libonnxruntime.so` (or to any value when ort ships its
//! own binaries). Without it they print a skip message and pass.
//!
//! Example (ORT from the PyPI wheel, no ort binary download):
//! ```text
//! export ORT_LIB_LOCATION=<dir with libonnxruntime.so> ORT_PREFER_DYNAMIC_LINK=1
//! export LD_LIBRARY_PATH=$ORT_LIB_LOCATION ANNO_BH7_ORT_LIB=$ORT_LIB_LOCATION
//! cargo test -p anno --test bughunt7
//! ```
#![cfg(feature = "onnx")]

use std::collections::BTreeSet;
use std::path::PathBuf;

fn ort_ready(test: &str) -> bool {
    match std::env::var_os("ANNO_BH7_ORT_LIB") {
        Some(_) => true,
        None => {
            eprintln!("skipping {test}: set ANNO_BH7_ORT_LIB to run ONNX Runtime tests");
            false
        }
    }
}

fn data(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("bughunt7_data")
        .join(name)
}

// =============================================================================
// TPLinker (backends/tplinker.rs, ONNX path)
// =============================================================================

mod tplinker {
    use super::*;
    use anno::backends::inference::RelationExtractor;
    use anno::backends::tplinker::TPLinker;

    type Triple = (String, String, String);

    fn run(fixture: &str, text: &str) -> (Vec<(String, usize, usize)>, BTreeSet<Triple>) {
        let m = TPLinker::from_local(&data(fixture)).expect("load tplinker fixture");
        assert!(m.is_neural());
        let out = m
            .extract_with_relations(text, &[], &[], 0.5)
            .expect("extract");
        let ents = out
            .entities
            .iter()
            .map(|e| (e.text.clone(), e.start(), e.end()))
            .collect();
        let rels = out
            .relations
            .iter()
            .map(|r| {
                (
                    out.entities[r.head_idx].text.clone(),
                    r.relation_type.clone(),
                    out.entities[r.tail_idx].text.clone(),
                )
            })
            .collect();
        (ents, rels)
    }

    fn t(h: &str, r: &str, o: &str) -> Triple {
        (h.to_string(), r.to_string(), o.to_string())
    }

    /// decode_relations must index the token-level handshaking sequence by
    /// token position, not by character offset.
    /// "[CLS] alice met bob [SEP]": the relation logit sits at token pair (1, 3).
    #[test]
    fn tplinker_relation_is_read_at_token_positions_not_char_offsets() {
        if !ort_ready("tplinker_relation_is_read_at_token_positions_not_char_offsets") {
            return;
        }
        let (ents, rels) = run("tplinker_tokpos", "alice met bob");
        assert!(ents.iter().any(|e| e.0 == "alice") && ents.iter().any(|e| e.0 == "bob"));
        assert!(
            rels.contains(&t("alice", "met", "bob")),
            "entities {ents:?}; relations {rels:?}; expected (alice, met, bob)"
        );
    }

    /// Character-offset indexing, other side: with "a b" the char starts (0, 2) address the
    /// ([CLS], b) cell, so a logit there yields relations between a and b.
    #[test]
    fn tplinker_cls_cell_does_not_create_a_relation() {
        if !ort_ready("tplinker_cls_cell_does_not_create_a_relation") {
            return;
        }
        let (ents, rels) = run("tplinker_cls_cell", "a b");
        assert_eq!(ents.len(), 2, "{ents:?}");
        assert!(
            rels.is_empty(),
            "only the ([CLS], b) cell is set; got relations {rels:?}"
        );
    }
}

// =============================================================================
// BERT token classification (backends/onnx.rs, BertNEROnnx::decode_output)
// =============================================================================

mod bert {
    use super::*;
    use anno::backends::onnx::{BertNERConfig, BertNEROnnx};

    fn ents(fixture: &str, text: &str) -> Vec<(String, String, usize, usize)> {
        let dir = data(fixture);
        let m = BertNEROnnx::with_config(dir.to_str().unwrap(), BertNERConfig::default())
            .expect("load bert fixture");
        m.extract_entities(text, None)
            .expect("extract")
            .into_iter()
            .map(|e| {
                (
                    e.text.clone(),
                    e.entity_type.as_label().to_string(),
                    e.start(),
                    e.end(),
                )
            })
            .collect()
    }

    /// An O-tagged token that starts at the previous token's end with an
    /// alphanumeric char counts as a subword continuation (`byte_adjacent`),
    /// so in unspaced CJK text every following ideograph is absorbed:
    /// B-LOC/I-LOC on 北/京 becomes "北京工作".
    #[test]
    fn bert_cjk_entity_is_not_extended_to_the_whole_clause() {
        if !ort_ready("bert_cjk_entity_is_not_extended_to_the_whole_clause") {
            return;
        }
        let got = ents("bert_cjk", "我在北京工作。");
        assert_eq!(got, vec![("北京".to_string(), "LOC".to_string(), 2, 4)]);
    }
}

// =============================================================================
// GLiNER (backends/gliner_onnx), loaded from a fixture HF cache
// =============================================================================

mod gliner {
    use super::*;
    use anno::backends::{GLiNERConfig, GLiNEROnnx};

    fn set_hf_env() {
        static ONCE: std::sync::Once = std::sync::Once::new();
        ONCE.call_once(|| {
            std::env::set_var("HF_HOME", data("hf_home"));
            std::env::set_var("ANNO_NO_DOWNLOADS", "1");
            std::env::remove_var("HF_HUB_CACHE");
        });
    }

    fn ents(repo: &str, text: &str, types: &[&str]) -> Vec<(String, usize, usize)> {
        set_hf_env();
        let cfg = GLiNERConfig {
            prefer_quantized: false,
            prompt_cache_size: 0,
            ..Default::default()
        };
        let m = GLiNEROnnx::with_config(repo, cfg).expect("load gliner fixture");
        m.extract(text, types, 0.5)
            .expect("extract")
            .into_iter()
            .map(|e| (e.text.clone(), e.start(), e.end()))
            .collect()
    }

    /// Control: span-level layout [1, words, max_width, classes] decodes
    /// "John Smith" and the greedy flat decoder drops the weaker nested "John".
    #[test]
    fn gliner_span_model_decodes_multiword_span() {
        if !ort_ready("gliner_span_model_decodes_multiword_span") {
            return;
        }
        let got = ents("bh7/gliner-span", "Call John Smith now", &["person"]);
        assert_eq!(got, vec![("John Smith".to_string(), 5, 15)]);
    }

    /// Token-level GLiNER (span_mode "token_level", no span_idx input; the
    /// shipped GLINER_PII model) outputs [1, words, classes, 3] =
    /// (start, end, inside). decode_span_logits_4d reads it as
    /// [1, words, max_width, classes].
    #[test]
    fn gliner_token_level_output_is_decoded_as_start_end_inside() {
        if !ort_ready("gliner_token_level_output_is_decoded_as_start_end_inside") {
            return;
        }
        let got = ents("bh7/gliner-token", "Call John Smith now", &["person"]);
        assert_eq!(got, vec![("John Smith".to_string(), 5, 15)]);
    }
}

// =============================================================================
// W2NER (backends/w2ner)
// =============================================================================

mod w2ner {
    use super::*;
    use anno::backends::W2NER;
    use anno::Model;

    /// Li et al. 2022 (arXiv 2112.10070) Sec 3.3 / Fig. 1: "aching in legs and
    /// shoulders" has the discontinuous entity "aching in shoulders" = THW(4, 0)
    /// with NNW 0->1 and 1->4. Its words are {0, 1, 4}; "legs" and "and" are not
    /// part of it. decode_discontinuous_from_matrix only checks NNW(i, i+1) and
    /// turns every gap into another segment, so the segments always tile head..=tail.
    /// (No ONNX Runtime needed.)
    #[test]
    fn w2ner_discontinuous_entity_skips_gap_words() {
        let words = ["aching", "in", "legs", "and", "shoulders"];
        let n = words.len();
        let mut grid = vec![0.0f32; n * n * 3];
        let mut set = |i: usize, j: usize, rel: usize| grid[(i * n + j) * 3 + rel] = 1.0;
        set(0, 1, 1); // NNW aching -> in
        set(1, 4, 1); // NNW in -> shoulders
        set(4, 0, 2); // THW tail shoulders, head aching
        let m = W2NER::grid_to_matrix(&grid, n, 3, 0.5);
        let rows = W2NER::new().decode_discontinuous_from_matrix(&m, &words, 0.5);
        let segs: Vec<Vec<(usize, usize)>> = rows.into_iter().map(|r| r.1).collect();
        assert_eq!(segs, vec![vec![(0, 2), (4, 5)]]);
    }

    fn ents(fixture: &str, text: &str) -> Vec<(String, String)> {
        let m = W2NER::from_pretrained(data(fixture).to_str().unwrap()).expect("load w2ner");
        let mut v: Vec<(String, String)> = m
            .extract_entities(text, None)
            .expect("extract")
            .into_iter()
            .map(|e| (e.text.clone(), e.entity_type.as_label().to_string()))
            .collect();
        v.sort();
        v
    }

    /// The exported grid (scripts/export_w2ner_to_onnx.py) is over tokenizer
    /// positions ([CLS] john smith works [SEP]); the decoder treats the cell
    /// indices as whitespace-word indices, so THW(tail=smith, head=john) at
    /// token (2, 1) becomes words 1..=2 = "Smith works".
    #[test]
    fn w2ner_token_grid_is_mapped_to_words() {
        if !ort_ready("w2ner_token_grid_is_mapped_to_words") {
            return;
        }
        let got = ents("w2ner_tokgrid", "John Smith works");
        let texts: Vec<&str> = got.iter().map(|e| e.0.as_str()).collect();
        assert!(texts.contains(&"John Smith"), "{got:?}");
        assert!(!texts.contains(&"Smith works"), "{got:?}");
    }

    /// Word-level tokenizer (token == word). The grid holds logits: THW(1, 0)
    /// is a real entity; cell (2, 2) has argmax None (logits 10 / -10 / 2).
    /// grid_to_matrix thresholds raw logits at 0.5 instead of taking the argmax,
    /// and decode_from_matrix ignores its entity_type_idx, so every span is
    /// emitted once per configured label (PER, ORG, LOC).
    #[test]
    fn w2ner_one_entity_per_thw_cell_and_argmax_none_is_none() {
        if !ort_ready("w2ner_one_entity_per_thw_cell_and_argmax_none_is_none") {
            return;
        }
        let got = ents("w2ner_wordgrid", "John Smith works");
        let texts: Vec<&str> = got.iter().map(|e| e.0.as_str()).collect();
        assert_eq!(texts, vec!["John Smith"], "{got:?}");
    }
}
